930	static enum lwan_read_finalizer
931	post_data_finalizer(size_t total_read,
932	                    size_t buffer_size,
933	                    struct lwan_request *request,
934	                    int n_packets)
935	{
936	    struct lwan_request_parser_helper *helper = request->helper;
937	
938	    if (buffer_size == total_read)
939	        return FINALIZER_DONE;
940	
941	    /* For POST requests, the body can be larger, and due to small MTUs on
942	     * most ethernet connections, responding with a timeout solely based on
943	     * number of packets doesn't work.  Use keepalive timeout instead.  */
944	    if (UNLIKELY(time(NULL) > helper->error_when_time))
945	        return FINALIZER_ERROR_TIMEOUT;
946	
947	    /* In addition to time, also estimate the number of packets based on an
948	     * usual MTU value and the request body size.  */
949	    if (UNLIKELY(n_packets > helper->error_when_n_packets))
950	        return FINALIZER_ERROR_TIMEOUT;
951	
952	    return FINALIZER_TRY_AGAIN;
953	}
954	
955	static ALWAYS_INLINE int max(int a, int b)
956	{
957	    return (a > b) ? a : b;
958	}
959	
960	static ALWAYS_INLINE int calculate_n_packets(size_t total)
961	{
962	    /* 740 = 1480 (a common MTU) / 2, so that Lwan'll optimistically error out
963	     * after ~2x number of expected packets to fully read the request body.*/
964	    return max(1, (int)(total / 740));
965	}
